*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vScrenID = 'ULDSTF26301.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    // 결산기구분코드.(통합DB)
    var url = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=C&CD_ENG_NM=FISCYY_TP_CD";
    dts_FISCYY_TP_CD.DataID = url;
    dts_FISCYY_TP_CD.Reset();
    dts_FISCYY.DataID = "";
    dts_FISCYY.Reset();
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var str = "";
    for (var i = yyyy; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    //alert(str);
    cmb_FISCYY.CBData = str;
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
};
scwin.fn_Search = function() {
    var MKT_ID = $c.stf.getObjectValue(rdo_MKT_ID);
    var FISCYY = $c.stf.getObjectValue(cmb_FISCYY);
    var ISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    //var FISCYY_TP_CD = getObjectValue(cmb_FISCYY_TP_CD);
    //var CURR_UNIT_CD = getObjectValue(cmb_CURR_UNIT_CD);
    var ACNT_TP_CD = $c.stf.getObjectValue(cmb_ACNT_TP_CD);
    if (ISUR_CD == "") {
        $c.win.alert("[회사]를 입력하세요.");
        txb_ISUR_CD.focus();
        return;
    }
    var url = "/DisclosureCountStatistics.do?method=listFISC";
    url += "&MKT_ID=" + MKT_ID;
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&FISCYY=" + FISCYY;
    //url += "&FISCYY_TP_CD=" + FISCYY_TP_CD; // 분기
    //url += "&CURR_UNIT_CD=" + CURR_UNIT_CD; // 단위
    url += "&ACNT_TP_CD=" + ACNT_TP_CD; // 1:대차, 2:손익,3:이익잉여,4:현금흐름표
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (ACNT_TP_CD == "1" || ACNT_TP_CD == "2") {
        dts_Grid.DataID = url;
        dts_Grid.Reset();
        $c.cm.ShowWin(grd_Grid);
    } else if (ACNT_TP_CD == "3" || ACNT_TP_CD == "4") {
        dts_Grid2.DataID = url;
        dts_Grid2.Reset();
        $c.cm.ShowWin(grd_Grid2);
    }
};
scwin.fn_HideDebugCtrls = function() {
    //showObj(panel_debug, false);
    $c.stf.showObj(grd_Grid2, false);
    $c.stf.showObj(panel_mkt, false);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_GridToExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "요약재무정보", "", "2"); //엑셀 다운로드

};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "";
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (window.event.keyCode == 40) {
        //아래화살표눌렀을때 그리드로 포커스
        Grd_com_isur.focus();
    } else {
        if (window.event.keyCode == 13) {
            $c.cm.fn_com_Confirm_set();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.cmb_ACNT_TP_CD_OnSelChange = function() {
    var str = $c.stf.getObjectValue(cmb_ACNT_TP_CD);
    if (str == "1" || str == "2") {
        $c.stf.showObj(grd_Grid, true);
        $c.stf.showObj(grd_Grid2, false);
        dts_Grid2.removeAll();
    } else if (str == "3" || str == "4") {
        $c.stf.showObj(grd_Grid, false);
        dts_Grid.removeAll();
        $c.stf.showObj(grd_Grid2, true);
        grd_Grid2.style.left = grd_Grid.style.left;
        grd_Grid2.style.top = grd_Grid.style.top;
        grd_Grid2.setGridWidth(grd_Grid.getStyle("width"));
        grd_Grid2.setGridHeight(grd_Grid.getStyle("height"));
    }
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    var FISCAL_YYYY1 = dts_Grid.getCellData(1, "FISCAL_YYYY1");
    var FISCAL_YYYY2 = dts_Grid.getCellData(1, "FISCAL_YYYY2");
    var FISCAL_YYYY3 = dts_Grid.getCellData(1, "FISCAL_YYYY3");
    $c.cm.setColumnProp(grd_Grid, "FISCAL_YYYY1", "Name", FISCAL_YYYY1);
    $c.cm.setColumnProp(grd_Grid, "FISCAL_YYYY2", "Name", FISCAL_YYYY2);
    $c.cm.setColumnProp(grd_Grid, "FISCAL_YYYY3", "Name", FISCAL_YYYY3);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.dts_Grid2_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid2);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    var FISCAL_YYYY1 = dts_Grid2.getCellData(1, "FISCAL_YYYY1");
    var FISCAL_YYYY2 = dts_Grid2.getCellData(1, "FISCAL_YYYY2");
    var FISCAL_YYYY3 = dts_Grid2.getCellData(1, "FISCAL_YYYY3");
    $c.cm.setColumnProp(grd_Grid2, "FISCAL_YYYY1", "Name", FISCAL_YYYY1);
    $c.cm.setColumnProp(grd_Grid2, "FISCAL_YYYY2", "Name", FISCAL_YYYY2);
    $c.cm.setColumnProp(grd_Grid2, "FISCAL_YYYY3", "Name", FISCAL_YYYY3);
};
scwin.dts_Grid2_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid2);
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
